295	<body>
296	  <main>
297	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle" aria-pressed="false">
298	      <svg viewBox="0 0 400 400" width="400" height="400" aria-hidden="true" role="presentation">
299	        <circle cx="200" cy="200" r="200"/>
300	      </svg>
301	    </button>
302	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true" aria-label="Current color mode"></div>
303	    <div class="controls" role="group" aria-label="Circle controls">
304	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
305	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
306	    </div>
307	  </main>
308	  <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
309	  <div class="keyboard-hint" aria-label="Keyboard shortcuts: Space or Enter to toggle, C to cycle color, R to reset">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
310	
311	  <script>
312	    const CONFIG = {
313	      storageKey: 'circle-state',
314	      tapDelay: 300,
315	      colorShiftDuration: 500,
316	      colorModes: [
317	        { class: 'default', name: 'Default White' },
318	        { class: 'color-mode-1', name: 'Pink' },
319	        { class: 'color-mode-2', name: 'Teal' },
320	        { class: 'color-mode-3', name: 'Mint' }
321	      ],
322	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
323	    };
324	
325	    const el = {
326	      circle: document.getElementById('decorative-circle'),
327	      hint: document.getElementById('hint-text'),
328	      modeIndicator: document.getElementById('mode-indicator'),
329	      cycleBtn: document.getElementById('cycle-btn'),
330	      resetBtn: document.getElementById('reset-btn')
331	    };
332	
333	    let state = { active: false, colorMode: 0 };
334	    let lastTapTime = 0;
335	    let tapTimeout = null;
336	
337	    const getColorModeClass = (mode) => CONFIG.colorModes[mode].class;
338	    const getColorModeName = (mode) => CONFIG.colorModes[mode].name;
339	
340	    const storage = {
341	      save() {
342	        try {
343	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
344	        } catch {
345	          // Silently fail if localStorage is unavailable or quota exceeded
346	        }
347	      },
348	      load() {
349	        try {
350	          const saved = localStorage.getItem(CONFIG.storageKey);
351	          if (saved) {
352	            const parsed = JSON.parse(saved);
353	            if (parsed && typeof parsed === 'object') {
354	              state = { ...state, ...parsed };
355	            }
356	          }
357	        } catch {
358	          // Silently fail if parsing fails
359	        }
360	      }
361	    };
362	
363	    const updateClasses = () => {
364	      const colorClasses = CONFIG.colorModes.map(m => m.class);
365	      el.circle.classList.remove('active', ...colorClasses);
366	      el.circle.setAttribute('aria-pressed', state.active);
367	      if (state.active) el.circle.classList.add('active');
368	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
369	    };
370	
371	    const updateUI = () => {
372	      const mainText = state.active ? 'Active!' : 'Click to activate';
373	      let hintParts = [mainText];
374	
375	      if (CONFIG.isTouch) {
376	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
377	      } else {
378	        hintParts.push('Double-click to change color');
379	      }
380	
381	      el.hint.textContent = hintParts.join(' • ');
382	
383	      const showMode = state.active && state.colorMode > 0;
384	      el.modeIndicator.classList.toggle('visible', showMode);
385	      if (showMode) {
386	        const modeName = getColorModeName(state.colorMode);
387	        el.modeIndicator.textContent = modeName;
388	      }
389	    };
390	
391	    const applyState = () => {
392	      updateClasses();
393	      updateUI();
394	    };
395	
396	    const toggleActive = () => {
397	      state.active = !state.active;
398	      applyState();
399	      storage.save();
400	    };
401	
402	    const cycleColor = () => {
403	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
404	      state.active = true;
405	      el.circle.classList.add('color-shifting');
406	      setTimeout(() => el.circle.classList.remove('color-shifting'), CONFIG.colorShiftDuration);
407	      applyState();
408	      storage.save();
409	    };
410	
411	    const resetState = () => {
412	      state = { active: false, colorMode: 0 };
413	      applyState();
414	      storage.save();
415	    };
416	
417	    const handleDblClick = (e) => {
418	      e.preventDefault();
419	      cycleColor();
420	    };
421	
422	    const handleTouchEnd = (e) => {
423	      const now = Date.now();
424	      if (now - lastTapTime < CONFIG.tapDelay && lastTapTime > 0) {
425	        cycleColor();
426	        lastTapTime = 0;
427	        clearTimeout(tapTimeout);
428	      } else {
429	        lastTapTime = now;
430	        clearTimeout(tapTimeout);
431	        tapTimeout = setTimeout(() => { lastTapTime = 0; }, CONFIG.tapDelay);
432	      }
433	    };
434	
435	    const keyHandlers = {
436	      ' ': toggleActive,
437	      'enter': toggleActive,
438	      'c': cycleColor,
439	      'r': resetState
440	    };
441	
442	    const handleKeyDown = (e) => {
443	      const handler = keyHandlers[e.key.toLowerCase()];
444	      if (handler) {
445	        e.preventDefault();
446	        handler();
447	      }
448	    };
449	
450	    const initListeners = () => {
451	      el.circle.addEventListener('click', toggleActive);
452	      el.circle.addEventListener('dblclick', handleDblClick);
453	      el.circle.addEventListener('touchend', handleTouchEnd);
454	      el.circle.addEventListener('blur', () => {
455	        lastTapTime = 0;
456	        clearTimeout(tapTimeout);
457	      });
458	      document.addEventListener('keydown', handleKeyDown);
459	      el.cycleBtn.addEventListener('click', cycleColor);
460	      el.resetBtn.addEventListener('click', resetState);
461	    };
462	
463	    const initApp = () => {
464	      storage.load();
465	      applyState();
466	      initListeners();
467	      requestAnimationFrame(() => el.circle.focus());
468	    };
469	
470	    if (document.readyState === 'loading') {
471	      document.addEventListener('DOMContentLoaded', initApp);
472	    } else {
473	      initApp();
474	    }
475	  </script>
476	</body>
477	</html>
